private static void markDeposit(char[][] grid, int i, int j) {
    if (i < 0 || i >= grid.length || j < 0 || j >= grid[i].length || grid[i][j] != '@') {
        return;
    }
    grid[i][j] = '*'; // Mark the current cell as visited

    // Visit all 8 possible neighboring cells
    markDeposit(grid, i - 1, j); // North
    markDeposit(grid, i + 1, j); // South
    markDeposit(grid, i, j - 1); // West
    markDeposit(grid, i, j + 1); // East
    markDeposit(grid, i - 1, j - 1); // North-West
    markDeposit(grid, i - 1, j + 1); // North-East
    markDeposit(grid, i + 1, j - 1); // South-West
    markDeposit(grid, i + 1, j + 1); // South-East
}

