private static void dfs(char[][] grid, boolean[][] visited, int row, int col) {
    int numRows = grid.length;
    int numCols = grid[0].length;

    // Check for out-of-bounds or already visited or no oil pocket
    if (row < 0 || row >= numRows || col < 0 || col >= numCols || visited[row][col] || grid[row][col] != '@') {
        return;
    }

    visited[row][col] = true;

    // Visit all 8 neighboring cells
    for (int i = -1; i <= 1; i++) {
        for (int j = -1; j <= 1; j++) {
            if (i == 0 && j == 0) continue; // Skip the center cell
            dfs(grid, visited, row + i, col + j);
        }
    }
}

public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("The number of triangles N must be non-negative.");
    }

    if (N == 0) {
        return 1; // No triangles, only the original region
    }

    // The formula to calculate the maximum number of regions
    // R(N) = 2 + N(N + 1)
    return 2 + N * (N + 1);
}

public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("Number of triangles cannot be negative");
    }
    if (N == 0) {
        return 1; // A plane without any triangles has 1 region
    }
    // The formula to calculate the maximum number of regions created by N triangles
    // is derived from the fact that each new triangle can intersect all previous triangles
    // creating new regions.
    return N * (N + 1) + 2;
}

