    }
    // The formula to calculate the maximum number of regions is R(N) = 2 + N(N + 1) / 2
    return 2 + N * (N + 1) / 2;
}

public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("Number of triangles cannot be negative");
    }
    if (N == 0) {
        return 1; // The plane is not divided by any triangles
    }
    // The formula to calculate the maximum number of regions
    // divided by N triangles is given by R(N) = 2 * R(N-1) - 1
    // Starting with R(0) = 1, this can be simplified to 2^(N+1) - 1
    return (1 << (N + 1)) - 1;
}

