    if (N < 0) {
        throw new IllegalArgumentException("Number of triangles must be non-negative");
    }
    // The formula to calculate the maximum number of regions is:
    // R(N) = 2 * N^2 - 2 * N + 2
    return 2 * N * N - 2 * N + 2;
}

