public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || paths == null) {
        return "cannot be travelled";
    }

    boolean[][] visited = new boolean[n][n];
    Queue<int[]> queue = new LinkedList<>();
    queue.offer(start);
    visited[start[0]][start[1]] = true;

    int[][] directions = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }

        for (int[] path : paths) {
            if (path[0] == current[0] && path[1] == current[1]) {
                int newX = path[2];
                int newY = path[3];
                if (newX >= 0 && newX < n && newY >= 0 && newY < n && !visited[newX][newY]) {
                    queue.offer(new int[]{newX, newY});
                    visited[newX][newY] = true;
                }
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || end == null || paths == null || start.length != 2 || end.length != 2) {
        throw new IllegalArgumentException("Invalid input");
    }

    boolean[][] visited = new boolean[n][n];
    return canTravel(n, start[0], start[1], end[0], end[1], visited, paths) ? "can be travelled" : "cannot be travelled";
}

private static boolean canTravel(int n, int x, int y, int endX, int endY, boolean[][] visited, int[][] paths) {
    if (x < 0 || x >= n || y < 0 || y >= n || visited[x][y]) {
        return false;
    }

    if (x == endX && y == endY) {
        return true;
    }

    visited[x][y] = true;

    // Check if we can go to the right
    if (y + 1 < n && (paths[x][y] & 1) != 0 && canTravel(n, x, y + 1, endX, endY, visited, paths)) {
        return true;
    }

    // Check if we can go down
    if (x + 1 < n && (paths[x][y] & 2) != 0 && canTravel(n, x + 1, y, endX, endY, visited, paths)) {
        return true;
    }

    // Check if we can go to the left
    if (y - 1 >= 0 && (paths[x][y - 1] & 1) != 0 && canTravel(n, x, y - 1, endX, endY, visited, paths)) {
        return true;
    }

    // Check if we can go up
    if (x - 1 >= 0 && (paths[x - 1][y] & 2) != 0 && canTravel(n, x - 1, y, endX, endY, visited, paths)) {
        return true;
    }

    visited[x][y] = false;
    return false;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start.length != 2 || end.length != 2 || paths == null) {
        return "cannot be travelled";
    }

    boolean[][] visited = new boolean[n][n];
    Set<String> pathSet = new HashSet<>();
    for (int[] path : paths) {
        if (path.length != 4) {
            continue; // Invalid path, skip
        }
        int x1 = path[0], y1 = path[1], x2 = path[2], y2 = path[3];
        if (x1 < 0 || x1 >= n || y1 < 0 || y1 >= n || x2 < 0 || x2 >= n || y2 < 0 || y2 >= n) {
            continue; // Out of bounds, skip
        }
        pathSet.add(x1 + "," + y1 + "-" + x2 + "," + y2);
        pathSet.add(x2 + "," + y2 + "-" + x1 + "," + y1); // Add both directions
    }

    return canTravelFromStartToEnd(start[0], start[1], end[0], end[1], visited, pathSet) ? "can be travelled" : "cannot be travelled";
}

private static boolean canTravelFromStartToEnd(int startX, int startY, int endX, int endY, boolean[][] visited, Set<String> pathSet) {
    if (startX == endX && startY == endY) {
        return true;
    }
    if (startX < 0 || startX >= visited.length || startY < 0 || startY >= visited[0].length || visited[startX][startY]) {
        return false;
    }
    visited[startX][startY] = true;

    // Check all 4 possible directions
    String[] directions = {
        startX + "," + startY + "-" + (startX + 1) + "," + startY,
        startX + "," + startY + "-" + (startX - 1) + "," + startY,
        startX + "," + startY + "-" + startX + "," + (startY + 1),
        startX + "," + startY + "-" + startX + "," + (startY - 1)
    };

    for (String direction : directions) {
        if (pathSet.contains(direction) && canTravelFromStartToEnd(
            Integer.parseInt(direction.split("-")[1].split(",")[0]),
            Integer.parseInt(direction.split("-")[1].split(",")[1]),
            endX,
            endY,
            visited,
            pathSet
        )) {
            return true;
        }
    }
    return false;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
