        int x2 = path[2];
        int y2 = path[3];

        if (x1 < 0 || y1 < 0 || x2 < 0 || y2 < 0 || x1 >= n || y1 >= n || x2 >= n || y2 >= n) {
            continue;
        }

        pathSet.add(x1 + "," + y1 + "," + x2 + "," + y2);
        pathSet.add(x2 + "," + y2 + "," + x1 + "," + y1);
    }

    return dfs(startX, startY, endX, endY, visited, pathSet) ? "can be travelled" : "cannot be travelled";
}

private static boolean dfs(int x, int y, int endX, int endY, boolean[][] visited, Set<String> pathSet) {
    if (x == endX && y == endY) {
        return true;
    }

    if (x < 0 || y < 0 || x >= visited.length || y >= visited.length || visited[x][y]) {
        return false;
    }

    visited[x][y] = true;

    int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
    for (int[] dir : directions) {
        int newX = x + dir[0];
        int newY = y + dir[1];
        if (isValidPath(x, y, newX, newY, pathSet)) {
            if (dfs(newX, newY, endX, endY, visited, pathSet)) {
                return true;
            }
        }
    }

    visited[x][y] = false;
    return false;
}

private static boolean isValidPath(int x1, int y1, int x2, int y2, Set<String> pathSet) {
    return pathSet.contains(x1 + "," + y1 + "," + x2 + "," + y2);
}

