        int x = current[0];
        int y = current[1];

        for (int[] direction : directions) {
            int newX = x + direction[0];
            int newY = y + direction[1];

            if (newX >= 0 && newX < n && newY >= 0 && newY < n && !visited[newX][newY]) {
                if (pathSet.contains(x + "," + y + "," + newX + "," + newY) || pathSet.contains(newX + "," + newY + "," + x + "," + y)) {
