    int[] count2 = new int[26];

    for (char c : word1.toCharArray()) {
        count1[c - 'A']++;
    }

    for (char c : word2.toCharArray()) {
        count2[c - 'A']++;
    }

    int commonLetters = 0;
    for (int i = 0; i < 26; i++) {
        commonLetters += Math.min(count1[i], count2[i]);
    }

    int totalLength = word1.length() + word2.length();

    int gcd = gcd(commonLetters, totalLength);

    int numerator = commonLetters / gcd;
    int denominator = totalLength / gcd;

    return "appx(" + word1 + ", " + word2 + ") = " + (denominator == 1 ? numerator : numerator + "/" + denominator);
}

