int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<List<Integer>> tree = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        tree.add(new ArrayList<>());
    }
    for (int[] edge : edges) {
        tree.get(edge[0]).add(edge[1]);
        tree.get(edge[1]).add(edge[0]);
    }
    return dfs(0, -1, tree, hasApple);
}

private int dfs(int node, int parent, List<List<Integer>> tree, boolean[] hasApple) {
    int totalTime = 0;
    for (int child : tree.get(node)) {
        if (child == parent) continue;
        int childTime = dfs(child, node, tree, hasApple);
        if (childTime > 0 || hasApple[child]) {
            totalTime += childTime + 2;
        }
    }
    return totalTime;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Create adjacency list for the tree
    List<List<Integer>> graph = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        graph.add(new ArrayList<>());
    }
    for (int[] edge : edges) {
        graph.get(edge[0]).add(edge[1]);
        graph.get(edge[1]).add(edge[0]);
    }

    // Helper function to perform DFS and calculate the time
    return dfs(0, -1, graph, hasApple) * 2;
}

private int dfs(int node, int parent, List<List<Integer>> graph, boolean[] hasApple) {
    int totalTime = 0;
    for (int child : graph.get(node)) {
        if (child == parent) {
            continue; // Skip the parent node to avoid cycles
        }
        int childTime = dfs(child, node, graph, hasApple);
        if (childTime > 0 || hasApple[child]) {
            totalTime += childTime + 2; // Add 2 for the round trip to the child
        }
    }
    return totalTime;
}

