public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n == 1) return false;

    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    boolean[][][] dp = new boolean[n / 2 + 1][n + 1][sum + 1];
    dp[0][0][0] = true;

    for (int i = 1; i <= n / 2; i++) {
        for (int j = n - 1; j >= i; j--) {
            for (int k = 0; k <= sum; k++) {
                if (dp[i - 1][j][k]) {
                    dp[i][j + 1][k + nums[j]] = true;
                    dp[i][j][k] = true;
                }
            }
        }
    }

    for (int i = 1; i <= n / 2; i++) {
        for (int j = i; j <= n; j++) {
            int k = sum * i / j;
            if (sum * i % j == 0 && dp[i][j][k]) {
                return true;
            }
        }
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    boolean[][][] dp = new boolean[n / 2 + 1][n + 1][sum + 1];
    dp[0][0][0] = true;

    for (int i = 0; i < n; i++) {
        for (int j = Math.min(i + 1, n / 2); j >= 1; j--) {
            for (int k = 0; k <= sum; k++) {
                if (dp[j - 1][i][k]) {
                    dp[j][i + 1][k + nums[i]] = true;
                }
            }
        }
    }

    for (int i = 1; i <= n / 2; i++) {
        if (sum * i % n == 0 && dp[i][n][sum * i / n]) {
            return true;
        }
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }

    int n = nums.length;
    boolean[][][] dp = new boolean[n + 1][n / 2 + 1][totalSum + 1];
    dp[0][0][0] = true;

    for (int i = 1; i <= n; i++) {
        for (int j = Math.min(i, n / 2); j >= 1; j--) {
            for (int k = 0; k <= totalSum; k++) {
                dp[i][j][k] = dp[i - 1][j][k];
                if (k >= nums[i - 1]) {
                    dp[i][j][k] = dp[i][j][k] || dp[i - 1][j - 1][k - nums[i - 1]];
                }
            }
        }
    }

    for (int j = 1; j <= n / 2; j++) {
        if (totalSum * j % n == 0 && dp[n][j][totalSum * j / n]) {
            return true;
        }
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }

    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    Arrays.sort(nums);

    for (int i = 1; i <= nums.length / 2; i++) {
        if (sum * i % nums.length == 0 && canSplit(nums, 0, sum * i / nums.length, i, new boolean[nums.length])) {
            return true;
        }
    }

    return false;
}

private boolean canSplit(int[] nums, int start, int target, int count, boolean[] used) {
    if (count == 0) {
        return target == 0;
    }
    for (int i = start; i < nums.length; i++) {
        if (!used[i] && (i == 0 || nums[i] != nums[i - 1] || used[i - 1])) {
            used[i] = true;
            if (target >= nums[i] && canSplit(nums, i + 1, target - nums[i], count - 1, used)) {
                return true;
            }
            used[i] = false;
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n == 1) return false;

    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    boolean[][][] dp = new boolean[n / 2 + 1][sum + 1][n + 1];
    dp[0][0][0] = true;

    for (int i = 1; i <= n; i++) {
        int num = nums[i - 1];
        for (int j = Math.min(i / 2, n - i / 2); j >= 1; j--) {
            for (int k = sum; k >= num; k--) {
                for (int l = i; l >= 1; l--) {
                    if (dp[j - 1][k - num][l - 1]) {
                        dp[j][k][l] = true;
                    }
                }
            }
        }
    }

    for (int i = 1; i <= n / 2; i++) {
        for (int j = 1; j < sum; j++) {
            if (dp[i][j][i] && j * n == sum * i) {
                return true;
            }
        }
    }

    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length < 2) {
        throw new IllegalArgumentException("Cost array must have at least two elements.");
    }

    int n = cost.length;
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }

    return Math.min(dp[n - 1], dp[n - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length < 2) {
        throw new IllegalArgumentException("Cost array must contain at least two elements.");
    }

    int n = cost.length;
    int first = cost[0];
    int second = cost[1];

    for (int i = 2; i < n; i++) {
        int current = cost[i] + Math.min(first, second);
        first = second;
        second = current;
    }

    return Math.min(first, second);
}

