public boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() < (1 << k) + k - 1) {
        return false;
    }

    Set<String> seen = new HashSet<>();

    for (int i = 0; i <= s.length() - k; i++) {
        String substring = s.substring(i, i + k);
        seen.add(substring);
        if (seen.size() == (1 << k)) {
            return true;
        }
    }

    return false;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() < k) {
        return false;
    }

    int totalSubstrings = 1 << k; // 2^k
    boolean[] found = new boolean[totalSubstrings];

    for (int i = 0; i <= s.length() - k; i++) {
        int num = 0;
        for (int j = 0; j < k; j++) {
            num = num * 2 + (s.charAt(i + j) - '0');
        }
        found[num] = true;
    }

    for (boolean b : found) {
        if (!b) {
            return false;
        }
    }

    return true;
}

