public int minInsertions(String s) {
    int open = 0; // Track the number of open parentheses '('
    int insertions = 0; // Track the number of insertions needed

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            open++;
        } else {
            // If we find a closing parenthesis ')'
            if (open > 0) {
                // If there is an open parenthesis matching it
                open--;
            } else {
                // If no matching open parenthesis, we need to insert one
                insertions++;
            }
            // Check for two consecutive closing parentheses
            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                i++; // Skip the next parenthesis as it matches this one
            } else {
                // If there is no next parenthesis or it's not a closing parenthesis, insert one
                insertions++;
            }
        }
    }

    // After processing the string, any unmatched open parentheses need to be closed
    insertions += open * 2; // Each open parenthesis needs two closing ones

    return insertions;
}

public int minInsertions(String s) {
    int insertions = 0;
    int balance = 0; // Tracks the balance of parentheses

    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == '(') {
            balance++;
        } else {
            balance--;
        }

        // If balance is negative, we need to insert '(' to balance it
        if (balance == -1) {
            insertions++;
            balance = 1; // Effectively inserting '(' and making balance 0 + 1
        }
    }

    // If balance is positive, we need to insert that many ')' to balance it
    insertions += balance;

    return insertions;
}

public int minInsertions(String s) {
    int open = 0; // Count of open parentheses needed
    int insertions = 0; // Insertions made so far

    for (char c : s.toCharArray()) {
        if (c == '(') {
            open += 2; // Each '(' needs two ')' to balance
            if (open % 2 == 1) {
                // If there's an odd number of open parentheses needed,
                // we need to insert a ')' to make it even
                insertions++;
                open--;
            }
        } else {
            open--; // A ')' closes one open slot
            if (open == -1) {
                // If open goes negative, we need to insert a '('
                insertions++;
                open = 1; // One open slot needed now
            }
        }
    }

    return insertions + open; // Add remaining open slots needed
}

public int minInsertions(String s) {
    int left = 0; // Track the number of unmatched '('
    int right = 0; // Track the number of insertions needed

    for (char c : s.toCharArray()) {
        if (c == '(') {
            if (right % 2 != 0) {
                // If there's an odd number of right insertions needed, we need to add a '(' to balance it
                left++;
                right--;
            }
            left++;
        } else {
            right++;
            if (left > 0 && right == 2) {
                // If we have an unmatched '(' and we need two ')' to balance, we use one '('
                left--;
                right -= 2;
            }
        }
    }

    // The total insertions needed is the sum of unmatched '(' and the remaining right insertions
    return left + right;
}

public int minInsertions(String s) {
    int leftBalance = 0; // To track the balance of '('
    int insertions = 0;  // To count the number of insertions needed

    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == '(') {
            leftBalance++;
        } else {
            // If we encounter a ')', we need a matching '('
            if (leftBalance > 0) {
                leftBalance--;
            } else {
                // No matching '(', so we need to insert one
                insertions++;
            }
            // Check if the next character is also ')', if so, it forms a ))
            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                i++; // Skip the next ')'
            } else {
                // If not, we need to insert an extra ')' to match the current '('
                insertions++;
            }
        }
    }
    // Add remaining unmatched '(' by adding an equal number of ')'
    insertions += leftBalance * 2;

    return insertions;
}

