public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer.");
    }

    // Generate all Fibonacci numbers less than or equal to k
    int a = 1, b = 1;
    while (b <= k) {
        int next = a + b;
        a = b;
        b = next;
    }

    // Use a greedy approach to find the minimum number of Fibonacci numbers
    int count = 0;
    while (k > 0) {
        while (a > k) {
            int temp = a;
            a = b - a;
            b = temp;
        }
        k -= a;
        count++;
    }

    return count;
}

