    if (n <= 0 || k <= 0) {
        return -1;
    }

    int count = 0;

    for (int i = 1; i <= n; i++) {
        if (n % i == 0) {
            count++;
            if (count == k) {
                return i;
            }
        }
    }

    return -1;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }

    int count = 0;
    for (int i = 1; i <= Math.sqrt(n); i++) {
        if (n % i == 0) {
            count++;
            if (count == k) {
                return i;
            }
            int correspondingFactor = n / i;
            if (correspondingFactor != i) {
                if (count + 1 == k) {
                    return correspondingFactor;
                }
            }
        }
    }

    return -1;
}

