public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder();
    int sum = 0;
    int remaining = n;

    for (int i = 0; i < n; i++) {
        for (char c = 'a'; c <= 'z'; c++) {
            int value = c - 'a' + 1;
            if (sum + value + (remaining - 1) * 26 >= k) {
                result.append(c);
                sum += value;
                remaining--;
                break;
            }
        }
    }

    return result.toString();
}

public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder();
    int remainingValue = k - n; // Start assuming all characters are 'a', which is value 1

    for (int i = 0; i < n; i++) {
        if (remainingValue >= 25) {
            result.append('z'); // Append 'z' if we can fully use up 25 remaining value
            remainingValue -= 25;
        } else {
            char currentChar = (char) ('a' + remainingValue); // Otherwise, append the character that uses up remaining value
            result.append(currentChar);
            remainingValue = 0;
        }
    }

    return result.reverse().toString(); // The above loop builds the string in reverse lexicographical order
}

public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder(n);
    int sum = 0;
    for (int i = 0; i < n; i++) {
        result.append('a');
        sum += 1;
    }
    k -= sum;
    for (int i = n - 1; i >= 0 && k > 0; i--) {
        int diff = Math.min(25, k);
        result.setCharAt(i, (char)('a' + diff));
        k -= diff;
    }
    return result.toString();
}

public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder();
    int remaining = k - n;

    for (int i = 0; i < n; i++) {
        int currentCharValue = Math.min(remaining, 25) + 1;
        result.append((char) ('a' + currentCharValue - 1));
        remaining -= currentCharValue;
    }

    return result.toString();
}

public String getSmallestString(int n, int k) {
    char[] result = new char[n];
    Arrays.fill(result, 'a');
    k -= n;

    for (int i = n - 1; i >= 0 && k > 0; i--) {
        int add = Math.min(25, k);
        result[i] += add;
        k -= add;
    }

    return new String(result);
}

