public static int singleNumber(int[] nums) {
    if (nums == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    int[] bitCount = new int[32];
    for (int num : nums) {
        for (int i = 0; i < 32; i++) {
            bitCount[i] += (num >> i) & 1;
        }
    }
    int result = 0;
    for (int i = 0; i < 32; i++) {
        if (bitCount[i] % 3 != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

