    for (int i = 0; i <= 9; i++) {
        if (i >= low) result.add(i);
        findSteppingNumbersHelper(result, i, low, high);
    }

    Collections.sort(result);
    return result;
}

private static void findSteppingNumbersHelper(List<Integer> result, int num, int low, int high) {
    if (num > high) return;

    int lastDigit = num % 10;

    if (lastDigit > 0) {
        int nextNum = num * 10 + (lastDigit - 1);
        if (nextNum >= low && nextNum <= high) result.add(nextNum);
        findSteppingNumbersHelper(result, nextNum, low, high);
    }

    if (lastDigit < 9) {
        int nextNum = num * 10 + (lastDigit + 1);
        if (nextNum >= low && nextNum <= high) result.add(nextNum);
        findSteppingNumbersHelper(result, nextNum, low, high);
    }
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) return result;

    for (int i = 0; i <= 9; i++) {
        bfs(low, high, i, result);
    }

    result.sort(Integer::compareTo);
    return result;
}

private static void bfs(int low, int high, int num, List<Integer> result) {
    Queue<Integer> queue = new LinkedList<>();
    queue.offer(num);

    while (!queue.isEmpty()) {
        int current = queue.poll();
        if (current >= low && current <= high) {
            result.add(current);
        }
        if (current == 0 || current > high) continue;

        int lastDigit = current % 10;
        int next1 = current * 10 + (lastDigit + 1);
        int next2 = current * 10 + (lastDigit - 1);

        if (lastDigit < 9 && next1 <= high) {
            queue.offer(next1);
        }
        if (lastDigit > 0) {
            queue.offer(next2);
        }
    }
}

