public static int countDigitOne(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("Input must be a non-negative integer.");
    }

    int count = 0;
    for (long m = 1; m <= n; m *= 10) {
        long a = n / m, b = n % m;
        count += (a + 8) / 10 * m + Math.min(Math.max(a % 10 - 1, 0) * m + b + 1, m);
    }
    return count;
}

public static int countDigitOne(int n) {
    if (n < 0) return 0;
    int count = 0;
    for (int digit = 1; digit <= n; digit *= 10) {
        int higherDigits = n / (digit * 10);
        int currentDigit = (n / digit) % 10;
        int lowerDigits = n % digit;

        if (currentDigit > 1) {
            count += (higherDigits + 1) * digit;
        } else if (currentDigit == 1) {
            count += higherDigits * digit + lowerDigits + 1;
        } else {
            count += higherDigits * digit;
        }
    }
    return count;
}

