public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int m = mat.length;
    int n = mat[0].length;
    int maxLength = 0;

    // Direction arrays for horizontal, vertical, diagonal, and anti-diagonal
    int[][] directions = {{0, 1}, {1, 0}, {1, 1}, {1, -1}};

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                for (int[] direction : directions) {
                    int x = i;
                    int y = j;
                    int length = 0;

                    while (x >= 0 && x < m && y >= 0 && y < n && mat[x][y] == 1) {
                        length++;
                        x += direction[0];
                        y += direction[1];
                    }

                    maxLength = Math.max(maxLength, length);
                }
            }
        }
    }

    return maxLength;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int m = mat.length;
    int n = mat[0].length;
    int[][][] dp = new int[m][n][4]; // 4 directions: 0=horizontal, 1=vertical, 2=diagonal, 3=anti-diagonal
    int maxLength = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                dp[i][j][0] = (j > 0) ? dp[i][j - 1][0] + 1 : 1; // horizontal
                dp[i][j][1] = (i > 0) ? dp[i - 1][j][1] + 1 : 1; // vertical
                dp[i][j][2] = (i > 0 && j > 0) ? dp[i - 1][j - 1][2] + 1 : 1; // diagonal
                dp[i][j][3] = (i > 0 && j < n - 1) ? dp[i - 1][j + 1][3] + 1 : 1; // anti-diagonal

                for (int k = 0; k < 4; k++) {
                    maxLength = Math.max(maxLength, dp[i][j][k]);
                }
            }
        }
    }

    return maxLength;
}

