public static int squarePermutations(int[] A) {
    if (A == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    boolean[] used = new boolean[A.length];
    int[] count = new int[1];
    backtrack(A, used, new int[A.length], count, 0);
    return count[0];
}

private static void backtrack(int[] A, boolean[] used, int[] current, int[] count, int pos) {
    if (pos == A.length) {
        count[0]++;
        return;
    }
    for (int i = 0; i < A.length; i++) {
        if (!used[i]) {
            if (pos == 0 || isPerfectSquare(current[pos - 1] + A[i])) {
                used[i] = true;
                current[pos] = A[i];
                backtrack(A, used, current, count, pos + 1);
                used[i] = false;
            }
            while (i + 1 < A.length && A[i] == A[i + 1]) {
                i++;
            }
        }
    }
}

private static boolean isPerfectSquare(int num) {
    int root = (int) Math.sqrt(num);
    return root * root == num;
}

public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) return 0;

    boolean[] used = new boolean[A.length];
    List<List<Integer>> results = new ArrayList<>();
    backtrack(A, new ArrayList<>(), used, results);

    return results.size();
}

private static void backtrack(int[] A, List<Integer> tempList, boolean[] used, List<List<Integer>> results) {
    if (tempList.size() == A.length) {
        results.add(new ArrayList<>(tempList));
        return;
    }

    for (int i = 0; i < A.length; i++) {
        if (used[i] || (i > 0 && A[i] == A[i - 1] && !used[i - 1])) continue;
        if (tempList.size() > 0 && !isPerfectSquare(tempList.get(tempList.size() - 1) + A[i])) continue;

        used[i] = true;
        tempList.add(A[i]);
        backtrack(A, tempList, used, results);
        used[i] = false;
        tempList.remove(tempList.size() - 1);
    }
}

