private static void backtrack(int[] A, boolean[] visited, int[] current, int depth, int[] count) {
    if (depth == A.length) {
        count[0]++;
        return;
    }

    for (int i = 0; i < A.length; i++) {
        if (!visited[i]) {
            if (depth == 0 || isPerfectSquare(current[depth - 1] + A[i])) {
                visited[i] = true;
                current[depth] = A[i];
                backtrack(A, visited, current, depth + 1, count);
                visited[i] = false;

                // Skip duplicates
                while (i < A.length - 1 && A[i] == A[i + 1]) {
                    i++;
                }
            }
        }
    }
}

