private static void backtrack(int[] A, boolean[] used, int[] current, int length, int[] count) {
    if (length == A.length) {
        count[0]++;
        return;
    }
    for (int i = 0; i < A.length; i++) {
        if (used[i] || (length > 0 && !isPerfectSquare(current[length - 1] + A[i]) || (i > 0 && A[i] == A[i - 1] && !used[i - 1]))) {
            continue;
        }
        used[i] = true;
        current[length] = A[i];
        backtrack(A, used, current, length + 1, count);
        used[i] = false;
    }
}

