public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) {
        return 0;
    }

    int[] count = new int[1];
    boolean[] visited = new boolean[A.length];

    backtrack(A, visited, count, -1);

    return count[0];
}

private static void backtrack(int[] A, boolean[] visited, int[] count, int prev) {
    boolean allVisited = true;
    for (boolean v : visited) {
        if (!v) {
            allVisited = false;
            break;
        }
    }
    if (allVisited) {
        count[0]++;
        return;
    }

    for (int i = 0; i < A.length; i++) {
        if (!visited[i]) {
            if (prev == -1 || isPerfectSquare(prev + A[i])) {
                visited[i] = true;
                backtrack(A, visited, count, A[i]);
                visited[i] = false;
            }
        }
    }
}

