public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int n = heights.length;
    int[] left = new int[n];
    int[] right = new int[n];
    int maxArea = 0;

    // Fill left array with the index of the nearest smaller element to the left of each element
    left[0] = -1;
    for (int i = 1; i < n; i++) {
        int j = i - 1;
        while (j >= 0 && heights[j] >= heights[i]) {
            j = left[j];
        }
        left[i] = j;
    }

    // Fill right array with the index of the nearest smaller element to the right of each element
    right[n - 1] = n;
    for (int i = n - 2; i >= 0; i--) {
        int j = i + 1;
        while (j < n && heights[j] >= heights[i]) {
            j = right[j];
        }
        right[i] = j;
    }

    // Calculate the max area
    for (int i = 0; i < n; i++) {
        maxArea = Math.max(maxArea, heights[i] * (right[i] - left[i] - 1));
    }

    return maxArea;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int maxArea = 0;
    int[] stack = new int[heights.length];
    int top = -1;

    for (int i = 0; i < heights.length; i++) {
        while (top != -1 && heights[stack[top]] >= heights[i]) {
            int height = heights[stack[top--]];
            int left = top == -1 ? -1 : stack[top];
            maxArea = Math.max(maxArea, height * (i - left - 1));
        }
        stack[++top] = i;
    }

    while (top != -1) {
        int height = heights[stack[top--]];
        int left = top == -1 ? -1 : stack[top];
        maxArea = Math.max(maxArea, height * (heights.length - left - 1));
    }

    return maxArea;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int n = heights.length;
    int[] stack = new int[n];
    int maxArea = 0;
    int index = 0;

    while (index < n) {
        if (stack.length == 0 || heights[stack[stack.length - 1]] <= heights[index]) {
            stack = addElement(stack, index++);
        } else {
            int top = stack[stack.length - 1];
            stack = removeElement(stack);
            int width = stack.length == 0 ? index : index - stack[stack.length - 1] - 1;
            maxArea = Math.max(maxArea, heights[top] * width);
        }
    }

    while (stack.length > 0) {
        int top = stack[stack.length - 1];
        stack = removeElement(stack);
        int width = stack.length == 0 ? index : index - stack[stack.length - 1] - 1;
        maxArea = Math.max(maxArea, heights[top] * width);
    }

    return maxArea;
}

private static int[] addElement(int[] stack, int element) {
    int[] newStack = new int[stack.length + 1];
    System.arraycopy(stack, 0, newStack, 0, stack.length);
    newStack[stack.length] = element;
    return newStack;
}

private static int[] removeElement(int[] stack) {
    int[] newStack = new int[stack.length - 1];
    System.arraycopy(stack, 0, newStack, 0, stack.length - 1);
    return newStack;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int n = heights.length;
    int[] left = new int[n];
    int[] right = new int[n];
    int[] stack = new int[n];
    int top = -1;

    // Fill left array with the first smaller element on the left of each bar
    for (int i = 0; i < n; i++) {
        while (top != -1 && heights[stack[top]] >= heights[i]) {
            top--;
        }
        left[i] = (top == -1) ? 0 : stack[top] + 1;
        stack[++top] = i;
    }

    top = -1; // Reset stack

    // Fill right array with the first smaller element on the right of each bar
    for (int i = n - 1; i >= 0; i--) {
        while (top != -1 && heights[stack[top]] >= heights[i]) {
            top--;
        }
        right[i] = (top == -1) ? n - 1 : stack[top] - 1;
        stack[++top] = i;
    }

    // Calculate the maximum area
    int maxArea = 0;
    for (int i = 0; i < n; i++) {
        maxArea = Math.max(maxArea, heights[i] * (right[i] - left[i] + 1));
    }

    return maxArea;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int maxArea = 0;
    java.util.Stack<Integer> stack = new java.util.Stack<>();
    int i = 0;

    while (i < heights.length) {
        if (stack.isEmpty() || heights[i] >= heights[stack.peek()]) {
            stack.push(i++);
        } else {
            int topIndex = stack.pop();
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            maxArea = Math.max(maxArea, heights[topIndex] * width);
        }
    }

    while (!stack.isEmpty()) {
        int topIndex = stack.pop();
        int width = stack.isEmpty() ? i : i - stack.peek() - 1;
        maxArea = Math.max(maxArea, heights[topIndex] * width);
    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int r = 0, c = 0, d = 0;

    for (int i = 0; i < result.length; i++) {
        result[i] = mat[r][c];

        // If the sum of the indices is even
        if ((r + c) % 2 == 0) {
            // If we are in the topmost row
            if (c == cols - 1) {
                r++;
            // If we are in the rightmost column
            } else if (r == 0) {
                c++;
            // Otherwise, move up diagonally
            } else {
                r--;
                c++;
            }
        } else {
            // If the sum of the indices is odd
            // If we are in the bottommost row
            if (r == rows - 1) {
                c++;
            // If we are in the leftmost column
            } else if (c == 0) {
                r++;
            // Otherwise, move down diagonally
            } else {
                r++;
                c--;
            }
        }
    }
    return result;
}

