public static int findSmallestInteger(int n) {
    // Convert the number to a character array of its digits
    char[] digits = String.valueOf(n).toCharArray();
    int length = digits.length;

    // Find the rightmost digit that is smaller than a digit next to it
    int i;
    for (i = length - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            break;
        }
    }

    // If no such digit is found, return -1
    if (i < 0) {
        return -1;
    }

    // Find the smallest digit on the right side of (i-th digit) that is larger than digits[i]
    int j;
    for (j = length - 1; j > i; j--) {
        if (digits[j] > digits[i]) {
            break;
        }
    }

    // Swap the found digits
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Reverse the digits to the right of the original position i
    Arrays.sort(digits, i + 1, length);

    // Convert the array of characters back to an integer
    try {
        return Integer.parseInt(new String(digits));
    } catch (NumberFormatException e) {
        return -1; // In case the number is out of integer range
    }
}

