public static List<String> centerSymmetricNumbers(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("The length of the center symmetric numbers must be a positive integer.");
    }

    return generateCenterSymmetricNumbers(n, n);
}

private static List<String> generateCenterSymmetricNumbers(int currentLength, int targetLength) {
    if (currentLength == 0) {
        return new ArrayList<>(Arrays.asList(""));
    }
    if (currentLength == 1) {
        return new ArrayList<>(Arrays.asList("0", "1", "8"));
    }

